typedef struct {
    unsigned char kind;      /* the pickup this is about */
    short id;                /* -1: every pickup of that kind */
    unsigned char test;      /* holding a thing, or being a character */
    unsigned char own_kind;  /* what sort of thing is held */
    short value;             /* which thing, or which character */
    short arg1;              /* the floor, or the charge asked for */
    short arg2;              /* the kind of charge asked for */
    unsigned char tainted;   /* the character's tainted twin counts too */
    short layer;             /* the order the mod checks them in */
    unsigned char flags;
    unsigned char loc;       /* which table the words are in */
    unsigned char var;       /* what {1} becomes */
    unsigned char var_kind;
    short var_id;
    unsigned char unique;    /* only one row of a group prints */
    unsigned char fallback;  /* English will do if this language has none */
    const char *modifier;
    const char *bullet;
    const char *var_text;
    const char *colour;
    const char *replace;
} eid_rule_t;

